def esc(s): return html.escape(str(s),quote=True)
def tr(fr,en,l): return en if l else fr
def url(key,l): return '/'+('en' if l else 'fr')+'/'+ROUTES[key][l].strip('/')+('/' if ROUTES[key][l] else '')
def surl(s,l): return '/'+('en' if l else 'fr')+'/'+s['slug'][l]+'/'
def a(href,label,cls='text-link'): return f'<a class="{cls}" href="{esc(href)}">{esc(label)}</a>'
def ph(fr,en,l): return f'<p class="placeholder">[À COMPLÉTER : {esc(tr(fr,en,l))}]</p>'
def rich(text):
 if text.startswith('[À COMPLÉTER'): return f'<p class="placeholder">{esc(text)}</p>'
 return f'<p>{esc(text)}</p>'
def icon(name): return f'<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24">{ICONS.get(name,ICONS["hr"])}</svg></span>'
def section(body,cls='',id=''):return f'<section class="section {cls}"'+(f' id="{id}"' if id else '')+f'><div class="wrap">{body}</div></section>'
def head(eyebrow,title,text='',link=''):return f'<div class="section-head"><div><span class="eyebrow">{esc(eyebrow)}</span><h2>{esc(title)}</h2></div>'+ (f'<p>{esc(text)}</p>' if text else link)+'</div>'
def image(name,alt,cls='',eager=False):
 dimensions={'offshore':(1600,1200),'office':(1200,800),'team':(800,1200),'people':(1200,800),'industry':(1200,900),'maritime':(1200,800)}
 w,h=dimensions.get(name,(1200,800))
 return f'<img class="{cls}" src="/assets/img/{name}.webp" alt="{esc(alt)}" width="{w}" height="{h}" '+('fetchpriority="high"' if eager else 'loading="lazy"')+' decoding="async">'

def header(l,key,alternate):
 nav=[('home',tr('Accueil','Home',l)),('about',tr('L’entreprise','Company',l))]
 links=''.join(f'<a href="{url(k,l)}"'+(' aria-current="page"' if key==k else '')+f'>{esc(v)}</a>' for k,v in nav)
 mega=''.join(f'<a href="{surl(s,l)}"><strong>{esc(s["short"][l])}</strong><small>{esc(s["intro"][l])}</small></a>' for s in SERVICES)
 links+=f'<details class="mega"><summary>{tr("Solutions","Solutions",l)}</summary><div class="mega-panel">{mega}</div></details>'
 links+=''.join(f'<a href="{url(k,l)}"'+(' aria-current="page"' if key==k else '')+f'>{esc(v)}</a>' for k,v in [('sectors',tr('Secteurs','Industries',l)),('careers',tr('Carrières','Careers',l)),('news',tr('Actualités','Insights',l)),('contact','Contact')])
 links+=a(url('quote',l),tr('Demander un devis','Request a quote',l),'btn small')
 return f'''<a class="skip" href="#main">{tr('Aller au contenu','Skip to content',l)}</a>
 <div class="topbar"><div class="wrap"><a href="tel:+242057753232">+242 05 775 3232</a><a class="email" href="mailto:secretariat@sascongo.com">secretariat@sascongo.com</a><span class="region">Pointe-Noire · {tr('Afrique Centrale','Central Africa',l)}</span><div class="languages" aria-label="{tr('Langue','Language',l)}"><a href="{alternate if l else url_for_current}" lang="fr" hreflang="fr" {'aria-current="true"' if not l else ''}>FR</a><span aria-hidden="true">/</span><a href="{url_for_current if l else alternate}" lang="en" hreflang="en" {'aria-current="true"' if l else ''}>EN</a></div></div></div>
 <header class="site-header"><div class="wrap nav-row"><a class="brand" href="{url('home',l)}" aria-label="SAS Congo — {tr('Ingénierie & Solutions RH — Accueil','Engineering & HR Solutions — Home',l)}"><img src="/assets/img/logo.webp" width="77" height="65" alt="SAS Congo"><span class="brand-copy"><strong>{tr('Ingénierie','Engineering',l)}</strong>{tr('& Solutions RH','& HR Solutions',l)}</span></a><button class="menu-toggle" aria-controls="navigation" aria-expanded="false" aria-label="{tr('Ouvrir le menu','Open menu',l)}">☰</button><nav class="primary-nav" id="navigation" aria-label="{tr('Navigation principale','Main navigation',l)}">{links}</nav></div></header>'''

def consent(l,form=''):
 return f'<label class="check"><input type="checkbox" name="consent" value="yes" required><span>{tr("J’accepte que mes données soient utilisées pour traiter cette demande.","I agree to the use of my information to process this request.",l)} <a href="{url("privacy",l)}"><u>{tr("Protection des données","Privacy information",l)}</u></a>.</span></label>'
def field(name,label,l,type='text',required=False,options=None,autocomplete=None):
 id='f-'+name
 attr=f' id="{id}" name="{name}"'+(' required' if required else '')+(f' autocomplete="{autocomplete}"' if autocomplete else '')
 if options is not None:el=f'<select{attr}>'+''.join(f'<option value="{esc(v)}">{esc(s)}</option>' for v,s in options)+'</select>'
 elif type=='textarea':el=f'<textarea{attr} rows="5"></textarea>'
 else:el=f'<input{attr} type="{type}"'+(' accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document"' if type=='file' else '')+(' min="0" step="1"' if type=='number' else '')+'>'
 return f'<div class="field"><label for="{id}">{esc(label)}'+(' *' if required else '')+f'</label>{el}</div>'
def form_start(name,l,extra=''):
 return f'<form class="form-shell" name="{name}-{l}" method="POST" action="{url("success",l)}" data-success="{url("success",l)}" data-netlify="true" netlify-honeypot="bot-field" {extra}><input type="hidden" name="form-name" value="{name}-{l}"><div class="honeypot" aria-hidden="true"><label>{tr("Ne pas remplir","Leave empty",l)}<input name="bot-field" tabindex="-1" autocomplete="off"></label></div>'
def form_end(l,label=None):return consent(l)+f'<p class="form-help">{tr("Les champs marqués * sont obligatoires.","Fields marked * are required.",l)}</p><div class="actions"><button class="btn" type="submit">{esc(label or tr("Envoyer la demande","Send request",l))}</button></div><p class="form-status" role="status" aria-live="polite"></p></form>'

def footer(l):
 sols=''.join(f'<li>{a(surl(s,l),s["short"][l],"")}</li>' for s in SERVICES if s['id'] in ['hr','training','representation','technical','sanitation'])
 useful=''.join(f'<li>{a(url(k,l),v,"")}</li>' for k,v in [('about',tr('L’entreprise','Company',l)),('international',tr('Présence internationale','International presence',l)),('references',tr('Références','References',l)),('careers',tr('Carrières','Careers',l)),('events',tr('Événements RH','HR events',l)),('application',tr('Déposer un CV','Submit a CV',l))])
 legal=''.join(a(url(k,l),TITLES[k][l],'') for k in ['legal','privacy','cookies'])
 nl=form_start('newsletter',l)+field('email','E-mail',l,'email',True,autocomplete='email').replace('f-email','newsletter-email')+consent(l)+f'<button class="btn small" type="submit">{tr("S’inscrire","Subscribe",l)}</button><p class="form-status" role="status"></p></form>'
 return f'''<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div><a class="footer-brand" href="{url('home',l)}"><img src="/assets/img/logo.webp" width="100" height="83" alt="SAS Congo"><strong>{tr('Ingénierie &<br>Solutions RH','Engineering &<br>HR Solutions',l)}</strong></a><p>{tr('Des solutions adaptées à votre activité, votre métier et votre environnement.','Solutions shaped around your business, industry and operating environment.',l)}</p>{ph('liens LinkedIn et Facebook officiels','official LinkedIn and Facebook links',l)}</div><div><h3>{tr('Nos solutions','Our solutions',l)}</h3><ul>{sols}</ul></div><div><h3>{tr('Liens utiles','Useful links',l)}</h3><ul>{useful}</ul></div><div><h3>{tr('Restons en contact','Stay in touch',l)}</h3><p>112 Avenue du Docteur Moé Poaty<br>Pointe-Noire, République du Congo</p><p><a href="tel:+242057753232">+242 05 775 3232</a><br><a href="mailto:secretariat@sascongo.com">secretariat@sascongo.com</a></p><a href="{url('contact',l)}">{tr('Tous nos bureaux →','All our offices →',l)}</a></div></div><details class="newsletter-panel"><summary>{tr('Recevoir nos actualités','Receive our updates',l)}</summary>{nl}</details><div class="footer-bottom"><span>© <span data-year>{date.today().year}</span> SAS Congo — {tr('Ingénierie & Solutions RH','Engineering & HR Solutions',l)}</span><div>{legal}<button type="button" class="text-link" data-cookie-settings>{tr('Préférences cookies','Cookie settings',l)}</button></div></div></div></footer>
 <aside class="cookie-banner" aria-label="{tr('Préférences cookies','Cookie preferences',l)}" hidden><h2>{tr('Votre confidentialité, votre choix.','Your privacy, your choice.',l)}</h2><p>{tr('Ce site n’utilise aucun outil de mesure d’audience. La carte Google Maps ne se charge qu’avec votre accord. Votre choix est enregistré sur cet appareil.','This site uses no analytics tools. Google Maps loads only with your permission. Your preference is stored on this device.',l)}</p><div class="actions"><button class="btn" data-cookie-choice="accept">{tr('Accepter la carte externe','Allow external map',l)}</button><button class="btn secondary" data-cookie-choice="reject">{tr('Refuser','Decline',l)}</button>{a(url('cookies',l),tr('En savoir plus','Learn more',l))}</div></aside>'''

def cta(l,service=None):
 target=url('quote',l)+(f'?service={service}' if service else '')
 return f'<section class="cta-band"><div class="wrap"><div><h2>{tr("Parlons de vos besoins en personnel.","Let’s talk about your workforce needs.",l)}</h2><p><a href="tel:+242057753232">+242 05 775 3232</a> · secretariat@sascongo.com</p></div><div class="actions">{a(target,tr("Demander un devis","Request a quote",l),"btn white")}</div></div></section>'
def page_hero(title,intro,l,oily=False,parent=None):
 bread=f'<a href="{url("home",l)}">{tr("Accueil","Home",l)}</a><span aria-hidden="true">/</span>'
 if parent:bread+=a(parent[0],parent[1],'')+'<span aria-hidden="true">/</span>'
 bread+=f'<span aria-current="page">{esc(title)}</span>'
 return f'<section class="page-hero {"oil" if oily else ""}"><div class="wrap"><nav class="breadcrumb" aria-label="{tr("Fil d’Ariane","Breadcrumb",l)}">{bread}</nav><span class="eyebrow">SAS Congo · {tr("Ingénierie & Solutions RH","Engineering & HR Solutions",l)}</span><h1>{esc(title)}</h1><p class="intro">{esc(intro)}</p></div></section>'
def service_cards(l,ids=None):
 services=[s for s in SERVICES if s['id'] in (ids or ['hr','training','representation','technical','sanitation'])]
 return '<div class="grid services-grid">'+''.join(f'<article class="card service-card reveal"><span class="card-number">SAS / {i+1:02d}</span>{icon(s["id"])}<h3>{esc(s["short"][l])}</h3><p>{esc(s["intro"][l])}</p>{a(surl(s,l),tr("Découvrir la solution","Explore this service",l))}</article>' for i,s in enumerate(services))+'</div>'
def job_cards(l,jobs=None):
 return ''.join(f'<article class="card job-card"><span class="badge">{tr("EXEMPLE · OFFRE FICTIVE","EXAMPLE · FICTIONAL VACANCY",l) if j["example"] else tr("OFFRE","VACANCY",l)}</span><h3>{esc(j["title"][l])}</h3><p>{esc(j["description"][l])}</p><div class="job-meta"><span>{esc(j["location"])}</span><span>{CONTRACTS[j["contract"]][l]}</span><span>{SECTORS[j["sector"]][l]}</span></div>{ph("date de publication d’une offre réelle","real vacancy publication date",l) if not j.get("publishedAt") else f"<time datetime='{esc(j['publishedAt'])}'>{esc(j['publishedAt'])}</time>"}{a(url("careers",l)+j["id"]+"/",tr("Voir la fiche","View details",l))}</article>' for j in (jobs or JOBS))
def article_cards(l,articles=None):
 return ''.join(f'<article class="card article-card" data-category="{art["category"]}">{image("offshore" if art["category"]=="oil" else "office",tr("Visuel d’illustration du sujet","Illustrative photograph",l),"article-cover")}<div><span class="badge">{tr("IDÉE ÉDITORIALE · À VALIDER","EDITORIAL IDEA · FOR APPROVAL",l) if not art["published"] else tr("ARTICLE","ARTICLE",l)}</span><span class="eyebrow">{CATEGORIES[art["category"]][l]}</span><h3>{esc(art["title"][l])}</h3>{a(url("news",l)+art["id"]+"/",tr("Consulter le modèle","View the template",l) if not art["published"] else tr("Lire l’article","Read article",l))}</div></article>' for art in (articles or ARTICLES))
def office_detail(o,l,cls=''):
 name=o['name'] if not l else o['name'].replace('(siège)','(headquarters)').replace('(Londres)','(London)').replace('Sénégal','Senegal')
 person=o['person'] if not l else o['person'].replace('Secrétariat','Secretariat')
 phones=' / '.join(f'<a href="tel:{re.sub(r"[^+0-9]","",p)}">{p}</a>' for p in o['phones'])
 address=o.get('address') or tr('[À COMPLÉTER : adresse du bureau de ','[À COMPLÉTER : office address for ',l)+o['city']+']'
 return f'<div class="{cls}"><span class="country">{esc(o["country"][l])}</span><h3>{esc(name)}</h3><p class="contact-name">{esc(person)}</p><p>{esc(address)}</p><p>{phones}<br><a href="mailto:{esc(o["email"])}">{esc(o["email"])}</a></p>'+ (rich(o['note'][l]) if o.get('note') else '')+'</div>'
def international_map(l):
 points=''.join(f'<circle class="map-dot" cx="{o["x"]}" cy="{o["y"]}" r="7"/><text class="map-city" x="{o["x"]+12}" y="{o["y"]+4}">{o["city"]}</text><circle class="map-button" cx="{o["x"]}" cy="{o["y"]}" r="18" role="button" tabindex="0" aria-label="{esc(o["city"])}" data-map-office="{i}"/>' for i,o in enumerate(OFFICES))
 svg=f'<svg viewBox="0 0 750 550" role="group" aria-label="{tr("Carte schématique des bureaux SAS","Schematic map of SAS offices",l)}"><path class="map-land" d="M213 172 261 126 353 110 425 128 490 151 529 205 591 223 614 283 589 316 552 350 531 406 489 475 464 516 425 475 395 413 387 342 340 301 285 295 240 270 212 236 184 215Z"/><path class="map-land" d="M611 380 627 360 641 390 622 433 609 438Z"/><path class="map-land" d="M391 34 407 22 424 35 418 55 403 64 389 53Z"/><path class="map-route" d="M410 50Q240 100 195 225M410 50Q555 170 465 325M195 225Q320 340 465 325M465 325L448 390M465 325Q565 280 550 150"/>{points}<circle class="map-dot" cx="550" cy="150" r="4"/><text class="map-city" x="570" y="155">Aberdeen*</text></svg>'
 tabs=''.join(f'<button type="button" data-office="{i}" aria-pressed="{str(i==0).lower()}" aria-controls="office-panel-{i}">{o["city"]}</button>' for i,o in enumerate(OFFICES))
 panels=''.join(f'<div id="office-panel-{i}" data-office-panel="{i}" {"hidden" if i else ""}>{office_detail(o,l,"office-preview")}</div>' for i,o in enumerate(OFFICES))
 return f'<div class="split"><div class="map-panel">{svg}<p class="map-note">{tr("Carte schématique, sans échelle. * Aberdeen : partenaires techniques, pas un bureau SAS.","Schematic map, not to scale. * Aberdeen: technical partners, not a SAS office.",l)}</p></div><div><span class="eyebrow">{tr("Notre réseau","Our network",l)}</span><h2>{tr("Une présence locale.<br>Une ouverture internationale.","Local presence.<br>International reach.",l)}</h2><div class="office-tabs" aria-label="{tr("Choisir un bureau","Select an office",l)}">{tabs}</div>{panels}</div></div>'

def home(l):
 hero=f'''<section class="hero">{image('offshore',tr('Plateforme offshore en mer — photo d’illustration, hors site SAS Congo','Offshore platform at sea — illustrative photo, not a SAS Congo site',l),'hero-image',True)}<div class="wrap"><span class="eyebrow">{tr('Expertise locale. Perspective internationale.','Local knowledge. International perspective.',l)}</span><h1>{tr('Le partenaire RH<br>des industries<br><em>d’Afrique Centrale.</em>','The HR partner<br>for the industries<br><em>of Central Africa.</em>',l)}</h1><p>{tr('Ingénierie, recrutement et solutions RH pour les secteurs pétrolier, parapétrolier, industriel et maritime. À terre comme en mer, avançons avec les bonnes compétences.','Engineering, recruitment and HR solutions for oil, oilfield services, industrial and maritime businesses. Onshore and offshore, move forward with the right skills.',l)}</p><div class="actions">{a(url('quote',l),tr('Demander un devis','Request a quote',l),'btn')}{a(url('application',l),tr('Déposer mon CV','Submit my CV',l),'btn ghost')}</div><p class="hero-caption">{tr('Photo d’illustration · À remplacer par un visuel de l’entreprise','Illustrative photo · Replace with a company photograph',l)}</p><div class="hero-foot"><span>Pointe-Noire / {tr('République du Congo','Republic of Congo',l)}</span><span>Onshore & Offshore</span><span>{tr('L’humain au cœur de vos opérations','People at the heart of your operations',l)} ↓</span></div></div></section>'''
 paths=f'<div class="pathbar"><div class="wrap paths"><a class="path" href="{url("quote",l)}">{icon("representation")}<div><b>{tr("Vous êtes une entreprise","For businesses",l)}</b><small>{tr("Construisons votre solution RH","Let’s shape your HR solution",l)}</small></div><span aria-hidden="true">↗</span></a><a class="path" href="{url("careers",l)}">{icon("hr")}<div><b>{tr("Vous êtes candidat","For candidates",l)}</b><small>{tr("Donnons une nouvelle direction à votre parcours","Explore your next career move",l)}</small></div><span aria-hidden="true">↗</span></a></div></div>'
 stats=[('années d’expérience validées','validated years of experience','Expérience','Experience'),('nombre de collaborateurs placés','number of people placed','Collaborateurs placés','People placed'),('nombre d’entreprises clientes','number of client companies','Entreprises clientes','Client companies'),('nombre de pays de présence validé','validated number of countries','Présence internationale','International presence')]
 stathtml='<div class="stats"><div class="wrap stats-grid">'+''.join(f'<div class="stat"><strong>{tr(label,enlabel,l)}</strong>{ph(fr,en,l)}</div>' for fr,en,label,enlabel in stats)+'</div></div>'
 solutions=section(head(tr('Nos solutions','Our solutions',l),tr('Les bonnes compétences.<br>Le bon accompagnement.','The right skills.<br>The right support.',l).replace('<br>',' '),tr('Cinq pôles d’activité pour relier vos enjeux humains, techniques et commerciaux.','Five business areas connecting your people, technical and commercial needs.',l))+service_cards(l))
 reasons=[('globe','Ancrage local, réseau international','Local roots, international connections','Une base à Pointe-Noire, un hub commercial à Londres et un réseau africain.','A Pointe-Noire base, a London commercial hub and an African network.'),('technical','Expertise Oil & Gas','Oil & Gas expertise','Des prestations RH et techniques reliées aux besoins de l’industrie.','HR and technical services connected to industry needs.'),('ship','Personnel onshore et offshore','Onshore and offshore personnel','Un recrutement adapté aux métiers et aux environnements d’intervention.','Recruitment tailored to roles and operating environments.'),('shield','Appui en droit social','Employment law support','Un accompagnement tenant compte du contexte juridique de votre demande.','Support informed by the legal context of your request.'),('training','Partenaires à Aberdeen','Aberdeen-based partners','Un lien technique pour les formations et l’assistance Oil & Gas.','Technical connections for training and Oil & Gas support.'),('hr','Coordination de vos besoins','Coordinating your requirements','Une offre qui réunit recrutement, gestion RH et accompagnement opérationnel.','An offer spanning recruitment, HR management and operational support.')]
 reasonhtml=''.join(f'<div class="reason">{icon(i)}<div><h3>{esc(tr(fr,en,l))}</h3><p>{esc(tr(p,q,l))}</p></div></div>' for i,fr,en,p,q in reasons)
 why=section(f'<div class="split"><div><span class="eyebrow">{tr("Pourquoi SAS Congo","Why SAS Congo",l)}</span><h2>{tr("Comprendre votre terrain.<br>Accompagner vos équipes.","Understand your environment.<br>Support your people.",l)}</h2><p>{tr("SAS Congo apporte des réponses adaptées à votre activité, votre métier et votre environnement, grâce à son ancrage local et à son expertise technique.","SAS Congo responds to your business, industry and operating environment through local knowledge and technical expertise.",l)}</p>{a(url("about",l),tr("Découvrir l’entreprise","Meet SAS Congo",l))}<div class="editorial-image" style="margin-top:35px">{image("people",tr("Réunion professionnelle — photo d’illustration, hors équipe SAS Congo","Professional meeting — illustrative photo, not the SAS Congo team",l))}<div class="image-note"><strong>{tr("L’humain au cœur des métiers","People at the heart of industry",l)}</strong>{tr("Photo d’illustration · À remplacer par une photo SAS Congo","Illustrative photo · Replace with a SAS Congo photograph",l)}</div></div></div><div>{reasonhtml}</div></div>','paper')
 sectors=section(head(tr('Vos métiers','Your industry',l),tr('L’expertise au contact du terrain.','Expertise connected to operations.',l))+sector_tiles(l))
 steps=[('Analyse du besoin','Understand the need','Définir le poste et son environnement.','Define the role and its environment.'),('Sourcing','Source talent','Identifier les profils dans le réseau.','Identify profiles through the network.'),('Sélection','Select candidates','Examiner les critères du poste.','Review the role requirements.'),('Mise à disposition','Mobilise personnel','Convenir des modalités de mobilisation.','Agree mobilisation arrangements.'),('Suivi & gestion RH','Follow-up & HR','Organiser le suivi et la gestion administrative.','Organise follow-up and administration.')]
 method=section(head(tr('Notre méthode','Our approach',l),tr('Un besoin clair. Un parcours structuré.','A clear brief. A structured process.',l))+'<div class="steps">'+''.join(f'<article class="step"><h3>{tr(fr,en,l)}</h3><p>{tr(p,q,l)}</p></article>' for fr,en,p,q in steps)+'</div>','paper')
 network=section(international_map(l),'dark')
 trust=section(head(tr('Nos références','References',l),tr('Ils nous font confiance.','Relationships built on trust.',l),link=a(url('references',l),tr('Voir cet espace','View this space',l)))+ph('liste validée des clients et autorisation d’affichage des logos','approved client list and permission to display logos',l)+'<div class="logo-track">'+''.join(f'<div class="logo-slot">{ph("logo client autorisé", "approved client logo",l)}</div>' for _ in range(4))+'</div>')
 careers=section(head(tr('Espace candidats','For candidates',l),tr('Votre talent. De nouvelles perspectives.','Your skills. New possibilities.',l),link=a(url('careers',l),tr('Explorer les offres','Explore vacancies',l)))+rich(tr('Les fiches ci-dessous sont des exemples fictifs de présentation. Elles ne correspondent à aucun poste ouvert.','The cards below are fictional presentation examples. They are not open vacancies.',l))+'<div class="grid three">'+job_cards(l)+'</div>','paper')
 news=section(head(tr('Actualités & idées','Insights & ideas',l),tr('Les sujets qui nous rapprochent.','Topics that connect us.',l),link=a(url('news',l),tr('Toutes les actualités','All insights',l)))+'<div class="grid three">'+article_cards(l,ARTICLES[:3])+'</div>')
 return hero+paths+stathtml+solutions+why+sectors+method+network+trust+careers+news+cta(l)

def sector_tiles(l):
 visuals={'oil':'offshore','services':'industry','industry':'industry','maritime':'maritime'}
 return '<div class="grid four">'+''.join(f'<a class="sector-card" href="{url("sectors",l)}#{k}">{image(visuals[k],tr("Visuel d’illustration du secteur ","Illustrative industry photo: ",l)+names[l])}<div><h3>{names[l]}</h3><span>{tr("Découvrir le secteur","Explore this industry",l)} <b aria-hidden="true">↗</b></span></div></a>' for k,names in SECTORS.items())+'</div>'

def about(l):
 content=page_hero(TITLES['about'][l],INTROS['about'][l],l)
 content+=section(f'<div class="split"><div class="editorial-image">{image("office",tr("Bureaux professionnels — illustration à remplacer par les locaux SAS Congo","Professional offices — replace with SAS Congo premises",l))}<div class="image-note"><strong>Pointe-Noire</strong>{tr("Un ancrage en République du Congo","Based in the Republic of Congo",l)}</div></div><div><span class="eyebrow">{tr("Notre ancrage","Our roots",l)}</span><h2>{tr("Des solutions RH au plus près de vos métiers.","HR solutions close to your industry.",l)}</h2><p>{tr("SAS Congo – Ingénierie & Solutions RH est spécialisée en ingénierie et en solutions ressources humaines en République du Congo et dans la sous-région Afrique Centrale.","SAS Congo – Engineering & HR Solutions specialises in engineering and human resources solutions in the Republic of Congo and the Central African region.",l)}</p><p>{tr("L’entreprise accompagne les secteurs pétrolier, parapétrolier, industriel, maritime et d’autres activités, avec des réponses adaptées à chaque environnement.","The company supports oil, oilfield services, industrial, maritime and other businesses with solutions suited to their operating context.",l)}</p>{ph("historique et année de création à confirmer ; une source tierce indique 2008","company history and founding year to confirm; a third-party source mentions 2008",l)}</div></div>')
 cards=[('Mission','Mission',tr('Apporter des réponses adaptées à l’activité, au métier et à l’environnement de chaque client.','Provide solutions suited to each client’s business, industry and environment.',l)),('Vision proposée','Proposed vision',tr('Accompagner le développement des industries africaines par les compétences et une gestion RH structurée.','Support African industries through skills and structured HR management.',l)),('Valeurs proposées','Proposed values',tr('Fiabilité, réactivité, conformité, sécurité et proximité.','Reliability, responsiveness, compliance, safety and proximity.',l))]
 content+=section(head(tr('Ce qui nous guide','What guides us',l),tr('Une mission concrète. Des repères à partager.','A practical purpose. Shared principles.',l))+'<div class="grid three">'+''.join(f'<article class="card"><h3>{tr(fr,en,l)}</h3><p>{esc(text)}</p>'+(ph('vision et valeurs proposées à valider par la direction','proposed vision and values to be approved by management',l) if i else '')+'</article>' for i,(fr,en,text) in enumerate(cards))+'</div>','paper')
 content+=section(head(tr('Direction','Leadership',l),tr('Le mot du Directeur Général','A message from the Managing Director',l))+ph('texte, nom, fonction et photo du Directeur Général','Managing Director message, name, role and photo',l)+head(tr('Notre équipe','Our team',l),tr('L’équipe dirigeante','Leadership team',l))+'<div class="grid three">'+''.join(f'<article class="card">{ph("photo, nom et fonction d’un membre de l’équipe dirigeante","leadership team member photo, name and role",l)}</article>' for _ in range(3))+'</div>')
 commitments=[('HSE & sécurité','HSE & safety','politique HSE, engagements de sécurité et certifications éventuelles','HSE policy, safety commitments and any certifications'),('Éthique & conformité','Ethics & compliance','charte éthique, dispositifs de conformité et responsabilités','ethics policy, compliance procedures and responsibilities'),('Non-discrimination','Non-discrimination','politique de recrutement équitable et engagements de non-discrimination','fair recruitment policy and non-discrimination commitments')]
 content+=section(head(tr('Engagements','Commitments',l),tr('Des engagements à documenter.','Commitments to document.',l))+'<div class="grid three">'+''.join(f'<article class="card">{icon("shield")}<h3>{tr(fr,en,l)}</h3>{ph(p,q,l)}</article>' for fr,en,p,q in commitments)+'</div>','paper')
 content+=section(head(tr('Le groupe SAS','The SAS group',l),tr('Une perspective au-delà des frontières.','A perspective beyond borders.',l))+rich(tr('Le groupe réunit le hub commercial de Londres, SAS International Group Ltd., et les implantations au Sénégal, en Côte d’Ivoire et en Angola. Le savoir-faire se déploie vers d’autres pays pétroliers africains.','The group connects the London commercial hub, SAS International Group Ltd., with locations in Senegal, Côte d’Ivoire and Angola. Its expertise is extending to other African oil-producing countries.',l))+a(url('international',l),tr('Explorer notre présence internationale','Explore our international presence',l)))
 return content+cta(l)

def faq_data(s,l):
 return [
 (tr('Comment définir le périmètre de la mission ?','How is the engagement scope defined?',l),tr('Un échange permet de préciser votre contexte, vos objectifs et les prestations attendues. Le périmètre est convenu avant l’intervention.','A discussion establishes your context, objectives and required services. The scope is agreed before work begins.',l)),
 (tr('Quels sont les délais et les tarifs ?','What are the timings and fees?',l),tr('Ils dépendent du besoin, de la disponibilité des compétences et du périmètre retenu. Une proposition est préparée après l’étude de votre demande.','They depend on the requirements, availability of skills and agreed scope. A proposal is prepared after your request is reviewed.',l)),
 (tr('Quelles informations transmettre pour un devis ?','What information is needed for a quote?',l),tr('Précisez le service recherché, les profils ou objectifs, le lieu, le calendrier souhaité et les coordonnées de votre entreprise.','Provide the service required, roles or objectives, location, preferred schedule and company contact details.',l)),
 (tr('Peut-on associer plusieurs prestations ?','Can several services be combined?',l),tr('Les besoins peuvent être étudiés ensemble. Les prestations retenues et leurs modalités restent à définir avec SAS Congo.','Requirements can be considered together. The selected services and arrangements must be agreed with SAS Congo.',l)),
 (tr('Comment sont traitées les exigences spécifiques du site ?','How are site-specific requirements handled?',l),tr('Les exigences du poste, du site et de votre organisation doivent être partagées lors du cadrage. Les qualifications et documents nécessaires sont examinés selon la mission.','Share role, site and organisational requirements when defining the brief. Qualifications and documentation are reviewed for the specific assignment.',l))]
def service(s,l):
 body=page_hero(s['title'][l],s['intro'][l],l,s['id'] in ['staffing','technical','training','representation'],(surl(SERVICES[0],l),SERVICES[0]['short'][l]) if s['id'] in ['staffing','recruitment','audit','tools','director','law','coaching'] else None)
 body+=section(f'<div class="split"><div><span class="eyebrow">{tr("Votre besoin","Your requirement",l)}</span><h2>{tr("Le besoin auquel nous répondons","The need we address",l)}</h2>{rich(s["need"][l])}</div><div><span class="eyebrow">{tr("Notre réponse","Our response",l)}</span><h2>{tr("Un accompagnement adapté à votre contexte","Support suited to your context",l)}</h2>{rich(s["response"][l])}</div></div>')
 body+=section(head(tr('Votre entreprise','Your business',l),tr('Ce que vous obtenez','What you receive',l))+'<div class="grid three">'+''.join(f'<article class="card">{icon("target")}<h3>{esc(v)}</h3></article>' for v in s['benefits'][l])+'</div>','paper')
 steps= [('Cadrer','Define','Préciser vos objectifs et vos contraintes.','Clarify objectives and constraints.'),('Préparer','Prepare','Définir le périmètre et les moyens.','Agree the scope and resources.'),('Intervenir','Deliver','Mettre en œuvre la prestation convenue.','Carry out the agreed service.'),('Suivre','Review','Faire le point sur la mission et ses suites.','Review the engagement and next steps.')]
 if s['id']=='representation':steps=[('Organiser la visite','Plan the visit','Planifier les visites de prospection ou de finalisation d’accords au Congo.','Plan prospecting visits or visits to finalise agreements in Congo.'),('Prospecter','Explore','Développer les réseaux commerciaux et rechercher des projets d’investissement en infrastructures ou matières premières.','Develop commercial networks and seek investment projects in infrastructure or raw materials.'),('Identifier','Identify','Identifier les clients potentiels et les interlocuteurs pertinents.','Identify potential clients and relevant contacts.'),('Négocier','Negotiate','Accompagner la négociation des termes et conditions des contrats dans l’intérêt du client.','Support negotiation of contract terms and conditions in the client’s interests.')]
 body+=section(head(tr('Déroulé proposé','Proposed process',l),tr('Comment ça se passe','How it works',l))+'<div class="steps four">'+''.join(f'<article class="step"><h3>{tr(fr,en,l)}</h3><p>{tr(p,q,l)}</p></article>' for fr,en,p,q in steps)+'</div>'+ph('modalités opérationnelles et livrables de ce service à valider','operational arrangements and deliverables for this service to approve',l))
 body+=section(f'<div class="body-copy"><span class="eyebrow">{tr("Pour qui","Who it is for",l)}</span><h2>{tr("Les entreprises concernées","Businesses we support",l)}</h2>{rich(s["audience"][l])}</div>','paper')
 if s['id']=='hr':body+=section(head(tr('Nos expertises RH','Our HR expertise',l),tr('Une solution pour chaque enjeu RH.','Support for each HR requirement.',l))+service_cards(l,['staffing','recruitment','audit','tools','director','law','coaching']))
 if s['id']=='training':
  body+=section(head(tr('Catalogue','Training catalogue',l),tr('Des programmes à préciser avec vous.','Programmes to define with you.',l))+'<div class="grid two">'+''.join(f'<article class="card">{icon("training")}<h3>{tr(fr,en,l)}</h3>{ph("intitulés, durées, public, prérequis et certifications des formations","course titles, duration, audience, prerequisites and certifications",l)}</article>' for fr,en in [('Formations RH','HR training'),('Formations Oil & Gas','Oil & Gas training')])+'</div>'+form_start('training',l)+'<h2>'+tr('Demander une formation intra-entreprise','Request in-company training',l)+'</h2><div class="form-grid">'+field('company',tr('Société','Company',l),l,required=True)+field('name',tr('Nom','Name',l),l,required=True)+field('email','E-mail',l,'email',True)+field('phone',tr('Téléphone','Phone',l),l,'tel')+field('participants',tr('Nombre de participants','Number of participants',l),l,'number')+field('location',tr('Lieu souhaité','Preferred location',l),l)+field('topic',tr('Sujet et objectifs','Topic and objectives',l),l,'textarea',True)+'</div>'+form_end(l),'paper')
 if s['id']=='representation':
  body+=section(head(tr('Un bureau clé en main','A turnkey office',l),tr('Un relais commercial, administratif et opérationnel.','Commercial, administrative and operational support.',l))+'<ul class="list">'+''.join(f'<li>{tr(fr,en,l)}</li>' for fr,en in [('Animation et développement des réseaux commerciaux','Commercial network development'),('Assistance administrative et lobbying auprès des administrations et gouvernements','Administrative support and liaison with public authorities'),('Suivi des opérations de sous-traitance','Subcontracting follow-up'),('Recherche de projets porteurs d’investissement','Identification of investment project opportunities')])+'</ul>'+rich(tr('Une formule modulable, avec la présence d’un partenaire local et les fonctions d’une filiale sans en porter le management ni les charges fixes. SAS Congo facilite les liens bilatéraux entre entreprises européennes, américaines, asiatiques et africaines.','A flexible arrangement providing a local partner and the functions of a subsidiary without its management burden or fixed overheads. SAS Congo facilitates bilateral business relationships between European, American, Asian and African companies.',l))+rich(tr('Zones couvertes : République du Congo et Afrique subsaharienne, selon le périmètre de la mission.','Coverage: the Republic of Congo and sub-Saharan Africa, depending on the engagement scope.',l))+a(url('contact',l)+'?subject=representation',tr('Planifier un échange','Arrange a conversation',l),'btn')+ph('outil de prise de rendez-vous et disponibilités validées','approved scheduling tool and availability',l),'paper')
 faq=faq_data(s,l)
 if s['id']=='sanitation':faq=[(tr('Quelles prestations sont disponibles ?','Which services are available?',l),tr('Le détail de ce pôle d’activité n’a pas encore été fourni. Contactez SAS Congo pour préciser votre besoin.','Details of this business area have not yet been supplied. Contact SAS Congo to discuss your needs.',l))]+faq[:3]
 body+=section(head(tr('Questions fréquentes','Frequently asked questions',l),tr('Les premiers repères pour votre projet.','A starting point for your project.',l))+'<div class="faq">'+''.join(f'<details><summary>{esc(q)}</summary><p>{esc(r)}</p></details>' for q,r in faq)+'</div>')
 body+=section(f'<div class="split"><div><h2>{tr("Parlons de ce service.","Let’s discuss this service.",l)}</h2>{a(url("quote",l)+"?service="+s["id"],tr("Demander un devis pour ce service","Request a quote for this service",l),"btn")}</div><div><h3>{tr("Services complémentaires","Related services",l)}</h3><ul class="list">'+''.join(f'<li>{a(surl(r,l),r["short"][l])}</li>' for r in SERVICES if r['id'] in (['hr','training','technical'] if s['id']!='hr' else ['training','representation','technical']) and r['id']!=s['id'])+'</ul></div></div>','paper')
 return body,faq

def sectors(l):
 body=page_hero(TITLES['sectors'][l],INTROS['sectors'][l],l)+section(sector_tiles(l))
 profiles={'oil':[['Opérateurs','Techniciens de maintenance','HSE','Logistique','Administratifs'],['Operators','Maintenance technicians','HSE roles','Logistics staff','Administrative staff']], 'services':[['Techniciens','Ingénieurs','Superviseurs','Logistique'],['Technicians','Engineers','Supervisors','Logistics staff']], 'industry':[['Production','Maintenance','Qualité','Ressources humaines'],['Production roles','Maintenance','Quality roles','Human resources']], 'maritime':[['Opérations portuaires','Coordination logistique','Maintenance','Administration'],['Port operations','Logistics coordination','Maintenance','Administration']]}
 for i,(k,names) in enumerate(SECTORS.items()):body+=section(f'<div class="split"><div><span class="eyebrow">{tr("Secteur","Industry",l)} / {i+1:02d}</span><h2>{names[l]}</h2><p>{tr("SAS Congo intervient auprès des entreprises de ce secteur avec des solutions RH et un accompagnement adapté au besoin exprimé.","SAS Congo supports businesses in this industry through HR solutions and support tailored to the stated need.",l)}</p>{a(surl(SERVICES[0],l),tr("Explorer les solutions RH","Explore HR solutions",l))}</div><div><h3>{tr("Exemples de familles de postes","Examples of role families",l)}</h3><p class="form-help">{tr("Exemples indicatifs ; aucune référence à des missions réalisées ou à des postes ouverts.","Illustrative examples; these do not represent completed assignments or open vacancies.",l)}</p><ul class="list">'+''.join(f'<li>{p}</li>' for p in profiles[k][l])+'</ul></div></div>','paper' if i%2==0 else '',k)
 return body+cta(l)
def international(l):
 body=page_hero(TITLES['international'][l],INTROS['international'][l],l)+section(international_map(l),'dark')
 body+=section(head(tr('Nos bureaux','Our offices',l),tr('Les coordonnées de votre interlocuteur.','Contact the relevant office.',l))+'<div class="grid offices">'+''.join(f'<article class="card">{office_detail(o,l,"office-card")}</article>' for o in OFFICES)+'</div>')
 body+=section(head(tr('Développement','Expansion',l),tr('Le savoir-faire SAS vers d’autres marchés.','SAS expertise across further markets.',l))+rich(tr('Pays en cours de développement : Mauritanie, Gabon et Namibie. Le Sénégal, la Côte d’Ivoire et l’Angola font également partie du déploiement vers les pays pétroliers africains.','Markets under development: Mauritania, Gabon and Namibia. Senegal, Côte d’Ivoire and Angola are also part of the expansion into African oil-producing countries.',l))+ph('statut, périmètre et coordonnées des développements en Mauritanie, au Gabon et en Namibie','status, scope and contact details for developments in Mauritania, Gabon and Namibia',l)+rich(tr('Aberdeen, Royaume-Uni : partenaires techniques pour les formations et l’assistance Oil & Gas. Londres : hub commercial SAS International Group Ltd.','Aberdeen, United Kingdom: technical partners for Oil & Gas training and support. London: the SAS International Group Ltd. commercial hub.',l)),'paper')
 return body+cta(l)
def references(l):
 return page_hero(TITLES['references'][l],INTROS['references'][l],l)+section(ph('liste validée des clients et autorisation d’affichage des logos ; Newpark, Aksa, Bourbon et SGMP sont uniquement des noms identifiés sur l’ancien site, à confirmer','approved client list and logo display permission; Newpark, Aksa, Bourbon and SGMP were only identified on the former site and require confirmation',l)+'<div class="logo-track">'+''.join(f'<div class="logo-slot">{ph("logo client validé","approved client logo",l)}</div>' for _ in range(4))+'</div>')+section(head(tr('Retours d’expérience','Client feedback',l),tr('Des témoignages à recueillir.','Testimonials to collect.',l))+'<div class="grid three">'+''.join(f'<article class="card"><h3>{tr("Emplacement témoignage","Testimonial placeholder",l)}</h3>{ph("citation authentique, auteur, fonction, entreprise et autorisation de publication","authentic quote, author, role, company and publication permission",l)}</article>' for _ in range(3))+'</div>','paper')+cta(l)

def careers(l):
 filt=f'<form class="filters" data-job-filters><div class="form-grid">'+field('keywords',tr('Mots-clés','Keywords',l),l,'search')+field('location',tr('Localisation','Location',l),l,options=[('',tr('Tous les lieux','All locations',l))]+[(loc,loc) for loc in sorted(set(j['location'] for j in JOBS))])+field('sector',tr('Secteur','Industry',l),l,options=[('',tr('Tous les secteurs','All industries',l))]+[(k,v[l]) for k,v in SECTORS.items()])+field('contract',tr('Contrat','Contract',l),l,options=[('',tr('Tous les contrats','All contracts',l))]+[(k,v[l]) for k,v in CONTRACTS.items()])+f'</div><label class="check"><input type="checkbox" name="remote" value="yes">{tr("Télétravail","Remote work",l)}</label><div class="actions"><button class="btn small" type="submit">{tr("Rechercher","Search",l)}</button><button class="btn secondary small" type="reset">{tr("Réinitialiser","Reset",l)}</button></div></form>'
 body=page_hero(TITLES['careers'][l],INTROS['careers'][l],l)+section(rich(tr('Démonstration : les trois offres sont fictives et marquées EXEMPLE. Aucune candidature ne peut être adressée à ces offres.','Demonstration: all three vacancies are fictional and marked EXAMPLE. Applications cannot be made to these vacancies.',l))+filt+f'<p class="result-count" data-job-count role="status">{tr("3 offres de démonstration","3 demonstration vacancies",l)}</p><div class="grid three" data-job-list>'+job_cards(l)+'</div><noscript><p>'+tr('Les filtres nécessitent JavaScript. Toutes les offres sont affichées.','Filters require JavaScript. All vacancies are displayed.',l)+'</p></noscript>')
 body+=section(f'<div class="split"><div><span class="eyebrow">{tr("Candidature spontanée","Speculative applications",l)}</span><h2>{tr("Votre parcours mérite d’être connu.","Let us get to know your experience.",l)}</h2><p>{tr("Présentez vos compétences, votre expérience et les métiers qui vous intéressent.","Share your skills, experience and the roles that interest you.",l)}</p>{a(url("application",l),tr("Déposer mon CV","Submit my CV",l),"btn")}</div><div><h3>{tr("Préparer sa candidature","Preparing your application",l)}</h3><ul class="list"><li>{tr("Présentez les expériences pertinentes pour le poste.","Highlight experience relevant to the role.",l)}</li><li>{tr("Vérifiez vos coordonnées et la lisibilité du CV.","Check your contact details and CV readability.",l)}</li><li>{tr("Indiquez uniquement les certifications que vous détenez.","Only list certifications you hold.",l)}</li></ul>{ph("à valider par l’entreprise : SAS Congo ne demande jamais d’argent pour un recrutement","company to validate: SAS Congo never charges candidates for recruitment",l)}</div></div>','paper')
 return body
def job_page(j,l):
 body=page_hero(j['title'][l],j['description'][l],l,parent=(url('careers',l),tr('Carrières','Careers',l)))
 body+=section(f'<div class="split"><div><span class="badge">{tr("EXEMPLE — AUCUN POSTE OUVERT","EXAMPLE — NOT AN OPEN VACANCY",l) if j["example"] else tr("OFFRE","VACANCY",l)}</span><h2>{tr("Description et missions","Description and responsibilities",l)}</h2>{rich(j["description"][l])}<ul class="list">'+''.join(f'<li>{esc(v)}</li>' for v in j['missions'][l])+f'</ul><h2>{tr("Profil recherché","Candidate profile",l)}</h2>{rich(j["profile"][l])}<h2>{tr("Avantages et conditions","Benefits and conditions",l)}</h2>{ph("avantages, rémunération, durée, conditions et critères d’une offre réelle","benefits, remuneration, duration, conditions and requirements for a real vacancy",l)}</div><aside class="card"><h3>{tr("Repères du poste","Role details",l)}</h3><p>{esc(j["location"])}<br>{CONTRACTS[j["contract"]][l]}<br>{SECTORS[j["sector"]][l]}</p>{ph("date de publication et date de clôture d’une offre réelle","publication and closing dates for a real vacancy",l)}'+(f'<button class="btn" type="button" disabled>{tr("Postuler — exemple indisponible","Apply — unavailable example",l)}</button><p class="form-help">'+tr('Pour présenter votre parcours, utilisez la candidature spontanée.','To share your experience, use the speculative application form.',l)+'</p>'+a(url('application',l),tr('Candidature spontanée','Speculative application',l)) if j['example'] else a(url('application',l)+'?position='+quote(j['title'][l]),tr('Postuler','Apply',l),'btn'))+'</aside></div>')
 return body
def application(l):
 labels=[('last_name','Nom','Last name','text',True,'family-name'),('first_name','Prénom','First name','text',True,'given-name'),('phone','Téléphone','Phone','tel',True,'tel'),('email','E-mail','E-mail','email',True,'email'),('city','Ville','City','text',True,'address-level2'),('country','Pays','Country','text',True,'country-name'),('position','Poste visé','Role sought','text',True,None),('experience','Années d’expérience','Years of experience','number',True,None)]
 form=form_start('application',l,'enctype="multipart/form-data"')+f'<h2>{tr("Votre candidature","Your application",l)}</h2><div class="form-grid">'+''.join(field(n,tr(fr,en,l),l,typ,req,autocomplete=aut) for n,fr,en,typ,req,aut in labels)+'</div>'
 form+=f'<fieldset style="margin-top:25px"><legend>{tr("Certifications (facultatif)","Certifications (optional)",l)}</legend><div class="choice-grid">'+''.join(f'<label class="check"><input type="checkbox" name="certifications" value="{cert}">{cert}</label>' for cert in ['BOSIET','HUET','H2S'])+'</div></fieldset>'+field('other_certifications',tr('Autres certifications','Other certifications',l),l)+field('cv',tr('Votre CV — PDF ou DOCX, 5 Mo maximum','Your CV — PDF or DOCX, maximum 5 MB',l),l,'file',True)+field('cover_letter',tr('Lettre de motivation (facultative)','Cover letter (optional)',l),l,'textarea')+ph('durée de conservation des CV, base légale, responsable du traitement et procédure d’exercice des droits','CV retention period, legal basis, data controller and rights request procedure',l)+form_end(l,tr('Envoyer ma candidature','Submit my application',l))
 return page_hero(TITLES['application'][l],INTROS['application'][l],l)+section(f'<div class="split" style="align-items:start"><div><span class="eyebrow">{tr("Espace candidats","For candidates",l)}</span><h2>{tr("Des informations utiles, un dossier clair.","Useful information. A clear application.",l)}</h2><p>{tr("Déposez un CV à jour et précisez le poste ou le domaine visé. Les certifications sont facultatives et doivent correspondre à votre parcours réel.","Upload an up-to-date CV and specify the role or field you are seeking. Certification information is optional and should reflect your actual qualifications.",l)}</p><p>{tr("Le dépôt d’un dossier ne constitue ni une offre d’emploi ni un engagement de recrutement.","Submitting an application is not a job offer or a commitment to recruit.",l)}</p>{a(url("privacy",l),tr("Protection de vos données","Your data and privacy",l))}</div><div>{form}</div></div>')

