 f=form_start('contact',l)+f'<h2>{tr("Écrivez-nous","Send us a message",l)}</h2><div class="form-grid">'
 for n,fr,en,typ,req in [('name','Nom','Name','text',True),('company','Société','Company','text',False),('role','Fonction','Role','text',False),('email','E-mail','E-mail','email',True),('phone','Téléphone','Phone','tel',False),('country','Pays','Country','text',True)]:f+=field(n,tr(fr,en,l),l,typ,req)
 f+=field('subject',tr('Objet','Subject',l),l,required=True,options=[('hr',tr('Solutions RH','HR solutions',l)),('training',tr('Formation','Training',l)),('representation',tr('Représentation','Representation',l)),('application',tr('Candidature','Application',l)),('other',tr('Autre','Other',l))])+field('message',tr('Message','Message',l),l,'textarea',True)+'</div>'+form_end(l)
 return f
