def quote_form(l):
 f=form_start('quote',l,'data-quote-form')+f'<div class="progress-label"><span data-step-label>{tr("Étape 1 sur 4","Step 1 of 4",l)}</span><span>{tr("Votre projet","Your project",l)}</span></div><progress max="4" value="1" aria-label="{tr("Progression de la demande","Request progress",l)}"></progress>'
 f+=f'<fieldset data-step><legend tabindex="-1">1. {tr("Quel est votre besoin ?","What do you need?",l)}</legend><p class="form-help">{tr("Sélectionnez une ou plusieurs solutions.","Select one or more services.",l)}</p><div class="choice-grid">'+''.join(f'<label class="choice"><input type="checkbox" name="services" value="{s["id"]}">{icon(s["id"])}<span>{esc(s["short"][l])}</span></label>' for s in SERVICES)+'</div></fieldset>'
 f+=f'<fieldset data-step><legend tabindex="-1">2. {tr("Précisez votre projet","Tell us about your project",l)}</legend><div class="form-grid">'+field('people',tr('Nombre de personnes','Headcount',l),l,'number')+field('profiles',tr('Profils ou objectifs','Roles or objectives',l),l,required=True)+field('environment',tr('Environnement','Environment',l),l,options=[('unspecified',tr('À préciser','To be defined',l)),('onshore','Onshore'),('offshore','Offshore'),('both',tr('Onshore et offshore','Onshore and offshore',l)),('na',tr('Non applicable','Not applicable',l))])+field('duration',tr('Durée envisagée','Expected duration',l),l)+field('start',tr('Date de démarrage souhaitée','Preferred start date',l),l,'date')+field('location',tr('Lieu d’intervention','Service location',l),l,required=True)+'</div></fieldset>'
 f+=f'<fieldset data-step><legend tabindex="-1">3. {tr("Votre entreprise","Your company",l)}</legend><div class="form-grid">'+''.join(field(n,tr(fr,en,l),l,typ,req) for n,fr,en,typ,req in [('company','Société','Company','text',True),('name','Nom du contact','Contact name','text',True),('role','Fonction','Role','text',True),('email','E-mail professionnel','Business email','email',True),('phone','Téléphone','Phone','tel',True),('country','Pays','Country','text',True)])+'</div></fieldset>'
 f+=f'<fieldset data-step><legend tabindex="-1">4. {tr("Récapitulatif et envoi","Review and submit",l)}</legend><dl class="recap" data-recap></dl><noscript><p>{tr("Vérifiez les champs renseignés ci-dessus avant l’envoi.","Review the fields above before submitting.",l)}</p></noscript>{consent(l)}</fieldset><div class="actions"><button class="btn secondary" type="button" data-back hidden>{tr("Retour","Back",l)}</button><button class="btn" type="button" data-next hidden>{tr("Continuer","Continue",l)}</button><button class="btn" type="submit">{tr("Envoyer ma demande","Submit my request",l)}</button></div><p class="form-status" role="status" aria-live="polite"></p></form>'
 return f
