def news(l):
 filterhtml=field('category',tr('Catégorie','Category',l),l,options=[('',tr('Toutes les catégories','All categories',l))]+[(k,v[l]) for k,v in CATEGORIES.items()]).replace('<select','<select data-article-category')
 return page_hero(TITLES['news'][l],INTROS['news'][l],l)+section(rich(tr('Les six titres ci-dessous sont des propositions éditoriales SEO. Aucun article factuel ou juridique n’est publié sans validation.','The six titles below are proposed SEO editorial topics. No factual or legal article is published without approval.',l))+filterhtml+'<div class="grid three" style="margin-top:30px">'+article_cards(l)+'</div>')
def article_page(art,l):
 if art['published']:
  body=page_hero(art['title'][l],art.get('summary',['',''])[l],l,parent=(url('news',l),tr('Actualités','Insights',l)))
  content=f'<article class="article-layout"><div class="article-meta"><span>{esc(art.get("author",""))}</span><time datetime="{esc(art.get("publishedAt",""))}">{esc(art.get("publishedAt",""))}</time><span>{esc(art.get("readingTime",["",""])[l])}</span></div>'
  for part in art.get('sections',[]):
   content+=f'<h2>{esc(part["heading"][l])}</h2>'+''.join(rich(p) for p in part['paragraphs'][l])
  content+='</article>'
  return body+section(content)+section(head(tr('Articles liés','Related articles',l),tr('D’autres sujets à explorer.','More topics to explore.',l))+'<div class="grid three">'+article_cards(l,[x for x in ARTICLES if x['id']!=art['id']][:3])+'</div>','paper')
 body=page_hero(art['title'][l],tr('Modèle d’article — sujet proposé, contenu à rédiger et valider.','Article template — proposed topic, content to be written and approved.',l),l,parent=(url('news',l),tr('Actualités','Insights',l)))
 article=f'<article class="article-layout"><span class="badge">{tr("MODÈLE NON PUBLIÉ","UNPUBLISHED TEMPLATE",l)}</span><div class="article-meta"><span>{CATEGORIES[art["category"]][l]}</span><span>{tr("[À COMPLÉTER : date de publication]","[À COMPLÉTER : publication date]",l)}</span><span>{tr("[À COMPLÉTER : temps de lecture]","[À COMPLÉTER : reading time]",l)}</span></div>{ph("auteur et photo de l’article","article author and photo",l)}<h2>{tr("Introduction","Introduction",l)}</h2>{ph("introduction et angle éditorial validés","approved introduction and editorial angle",l)}<h2>{tr("Développement","Main discussion",l)}</h2>{ph("corps de l’article, sources vérifiables et validation juridique si nécessaire","article body, verifiable sources and legal review when required",l)}<h2>{tr("Repères pratiques","Practical guidance",l)}</h2>{ph("conseils validés et conclusion de l’article","approved guidance and article conclusion",l)}<div class="share"><span>{tr("Partager le sujet proposé","Share the proposed topic",l)}</span><a rel="noopener noreferrer" target="_blank" href="https://www.linkedin.com/sharing/share-offsite/?url={quote(BASE+url_for_current,safe="")}">LinkedIn ↗</a><a rel="noopener noreferrer" target="_blank" href="https://www.facebook.com/sharer/sharer.php?u={quote(BASE+url_for_current,safe="")}">Facebook ↗</a><a href="mailto:?subject={quote(art["title"][l])}&amp;body={quote(BASE+url_for_current,safe="")}">E-mail ↗</a></div></article>'
 body+=section(article)+section(head(tr('Articles liés','Related articles',l),tr('D’autres sujets à explorer.','More topics to explore.',l))+'<div class="grid three">'+article_cards(l,[x for x in ARTICLES if x['id']!=art['id']][:3])+'</div>','paper')
 return body
