 form=form_start('event-interest',l)+f'<h2>{tr("Être informé d’un événement","Express interest in an event",l)}</h2><div class="form-grid">'+field('name',tr('Nom','Name',l),l,required=True)+field('email','E-mail',l,'email',True)+field('event',tr('Événement ou thème souhaité','Event or topic of interest',l),l,required=True)+'</div>'+form_end(l)
